def analyze(datasets):
    # 安全地获取各个查询的结果
    stock_q = next((d for d in datasets if 'stock_on_hand' in d.get('columns', [])), None)
    sold_q = next((d for d in datasets if 'units_sold' in d.get('columns', [])), None)
    po_q = next((d for d in datasets if 'po_number' in d.get('columns', [])), None)

    stock_rows = stock_q['rows'] if stock_q else []
    sold_rows = sold_q['rows'] if sold_q else []
    po_rows = po_q['rows'] if po_q else []

    # 构建映射表，处理空情况
    sold_map = {}
    name_map = {}
    for r in sold_rows:
        sku = r.get('sku')
        if sku:
            sold_map[sku] = float(r.get('units_sold', 0))
            # 优先使用 product_name，如果没有则使用 product_name_en 或 sku
            name_map[sku] = r.get('product_name', r.get('product_name_en', sku))

    data = {'Product': [], 'Stock': [], 'Units_Sold': [], 'Days_Left': []}

    for r in stock_rows:
        sku = r.get('sku')
        try:
            stock_val = float(r.get('stock_on_hand', 0))
        except (ValueError, TypeError):
            stock_val = 0.0

        sold_val = sold_map.get(sku, 0.0)

        # 计算可售天数
        days_left = None
        if sold_val > 0:
            days_left = round(stock_val / sold_val * 30, 1)

        # 确定产品名称
        # 优先级: name_map(来自sold) > r.get('product_name_en') > sku
        product_name = name_map.get(sku, r.get('product_name_en', sku))
        display_name = f"{product_name}（{sku}）"

        data['Product'].append(display_name)
        data['Stock'].append(stock_val)
        data['Units_Sold'].append(sold_val)
        data['Days_Left'].append(days_left)

    df = pd.DataFrame(data)

    # 确保数值列正确转换
    for col in ['Stock', 'Units_Sold', 'Days_Left']:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors='coerce')

    # 删除 Days_Left 为 NaN 的行（即销量为0的产品），因为它们无法计算可售天数
    # 注意：如果希望保留销量为0的产品，可以不去掉NaN，但通常计算天数需要销量>0
    # 根据原逻辑，days=None 会被 append，然后 dropna() 会去掉这些行
    df = df.dropna(subset=['Days_Left'])

    results = []
    for _, row in df.iterrows():
        title = f"{row['Product']} 库存与可售天数"
        detail = f"期末库存 {row['Stock']} 箱，9月已确认销量 {row['Units_Sold']} 箱，按当期销量折算预计还可售 {row['Days_Left']} 天。"
        results.append({
            'title': title,
            'detail': detail,
            'evidence': {
                'stock': row['Stock'],
                'units_sold': row['Units_Sold'],
                'days_left': row['Days_Left']
            }
        })

    # 低库存告警
    low_stock_df = df[df['Days_Left'] < 30]
    if len(low_stock_df) > 0:
        names = '、'.join(low_stock_df['Product'].tolist())
        min_days = float(low_stock_df['Days_Left'].min())
        results.append({
            'title': '补货告警',
            'detail': f"{names} 预计可售天数不足 30 天，需优先补货。",
            'evidence': {
                'alert_count': len(low_stock_df),
                'min_days': min_days
            }
        })

    # 采购单概况
    total_amt = 0.0
    statuses = {}
